        { text: 'Development of agriculture and industry increases demand for transport, trade, storage', kw: ['transport|storage|trade', 'agricultur|industr|primary|secondary'] },
        { text: 'Rising incomes increase demand for services; new IT-based services', kw: ['income', 'information technology|it-based|software|call centre'] }
